sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float position;
uniform float width;
uniform float softness;
uniform float intensity;
layout(color) uniform half4 color;
uniform float show;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    half4 soft = blurred.eval(coord);
    float lum = src.a > 0.0 ? dot(float3(src.rgb) / float(src.a), float3(0.2126, 0.7152, 0.0722)) : 0.0;
    float half_band = max(width, 0.0) * 0.5;
    float m = 1.0 - smoothstep(half_band, half_band + max(softness, 0.001), abs(lum - position));
    m *= float(src.a);
    float3 glowRgb = float3(soft.rgb) * float3(color.rgb) * max(intensity, 0.0) * m;
    half4 base = show > 0.5 ? src * half(m) : src;
    half4 mixed = half4(mix(base.rgb, soft.rgb, half(m)), base.a);
    return half4(min(mixed.rgb + half3(glowRgb), mixed.a), mixed.a);
}
